import React, { useState } from "react";

const cityDestinations = {
  Varanasi: [
    {
      name: "Dashashwamedh Ghat",
      description: "Experience the world-famous Ganga Aarti and the vibrant evening atmosphere.",
      bestTime: "Evening (6 PM - 8 PM)",
      safety: "Safe but crowded",
    },
    {
      name: "Kashi Vishwanath Temple",
      description: "A sacred temple dedicated to Lord Shiva, central to the spiritual soul of India.",
      bestTime: "Morning (5 AM - 9 AM)",
      safety: "Safe",
    },
  ],
  Jaipur: [
    {
      name: "Hawa Mahal",
      description: "The iconic 'Palace of Winds' with stunning pink sandstone architecture.",
      bestTime: "Morning (8 AM - 11 AM)",
      safety: "Safe",
    },
    {
      name: "Amber Fort",
      description: "Historic fort overlooking Maota Lake, offering elephant rides and royal charm.",
      bestTime: "Evening (4 PM - 6 PM)",
      safety: "Safe but hilly terrain",
    },
  ],
  Delhi: [
    {
      name: "India Gate",
      description: "Majestic war memorial surrounded by lush gardens and evening lights.",
      bestTime: "Evening (6 PM - 9 PM)",
      safety: "Safe",
    },
    {
      name: "Red Fort",
      description: "Historic Mughal fortress representing India’s rich past and culture.",
      bestTime: "Morning (9 AM - 12 PM)",
      safety: "Safe",
    },
  ],
};

export default function RoutePlanner({ tourist, onProceed }) {
  const [city, setCity] = useState("");
  const [destinations, setDestinations] = useState([]);

  const handleCitySelect = (e) => {
    const selectedCity = e.target.value;
    setCity(selectedCity);
    setDestinations(cityDestinations[selectedCity] || []);
  };

  return (
    <div
      style={{
        background: "linear-gradient(135deg, #FFB75E, #ED8F03)",
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        padding: "40px",
      }}
    >
      <div
        style={{
          backgroundColor: "rgba(255, 255, 255, 0.95)",
          borderRadius: "20px",
          padding: "30px",
          boxShadow: "0 8px 20px rgba(0, 0, 0, 0.2)",
          width: "90%",
          maxWidth: "700px",
          textAlign: "center",
        }}
      >
        <h1 style={{ color: "#A0522D", marginBottom: "10px" }}>🌍 My Journey</h1>
        <p style={{ fontSize: "1.1rem", color: "#333", marginBottom: "25px" }}>
          Welcome, <strong>{tourist.name}</strong>! Let's plan your journey.
        </p>

        {/* City Selection */}
        <div style={{ marginBottom: "20px" }}>
          <label style={{ fontWeight: "bold", color: "#5A2E0E" }}>Which city are you visiting?</label>
          <select
            value={city}
            onChange={handleCitySelect}
            style={{
              marginTop: "10px",
              padding: "10px",
              borderRadius: "10px",
              border: "1px solid #ddd",
              fontSize: "1rem",
              width: "80%",
            }}
          >
            <option value="">-- Select a City --</option>
            {Object.keys(cityDestinations).map((cityName) => (
              <option key={cityName} value={cityName}>
                {cityName}
              </option>
            ))}
          </select>
        </div>

        {/* Display Destinations */}
        {destinations.length > 0 ? (
          <>
            <h3 style={{ color: "#D2691E", marginBottom: "15px" }}>
              ✨ Top places to visit in {city}:
            </h3>
            <div
              style={{
                maxHeight: "300px",
                overflowY: "auto",
                textAlign: "left",
                paddingRight: "10px",
              }}
            >
              {destinations.map((dest, index) => (
                <div
                  key={index}
                  style={{
                    backgroundColor: "rgba(255, 255, 255, 0.9)",
                    borderRadius: "15px",
                    padding: "15px 20px",
                    marginBottom: "15px",
                    boxShadow: "0 4px 10px rgba(0, 0, 0, 0.1)",
                  }}
                >
                  <h3 style={{ color: "#D2691E", marginBottom: "5px" }}>📍 {dest.name}</h3>
                  <p style={{ marginBottom: "5px" }}>{dest.description}</p>
                  <p style={{ margin: "3px 0" }}>
                    <strong>🕐 Best Time:</strong> {dest.bestTime}
                  </p>
                  <p style={{ margin: "3px 0" }}>
                    <strong>🔒 Safety:</strong> {dest.safety}
                  </p>
                </div>
              ))}
            </div>

            <button
              onClick={onProceed}
              style={{
                marginTop: "25px",
                backgroundColor: "#FF7A00",
                border: "none",
                color: "white",
                padding: "12px 24px",
                borderRadius: "10px",
                fontSize: "1rem",
                cursor: "pointer",
                boxShadow: "0 4px 10px rgba(0, 0, 0, 0.2)",
              }}
            >
              🚶‍♂ Start My Journey
            </button>
          </>
        ) : (
          <p style={{ color: "#555", marginTop: "20px" }}>
            Select a city to view its tourist highlights 🌆
          </p>
        )}
      </div>
    </div>
  );
}
